/**
 * Quilt version and type constants
 */
export const QUILT_VERSION = '1.0';
export const MANIFEST_QUILT_TYPE = 'manifest';
export const ATTESTATION_QUILT_TYPE = 'attestation';

/**
 * Manifest Quilt - Empty placeholder (file hashes are in attestation)
 * This quilt is prepared by GitHub Action and sent to verification server
 * The verification server will upload it to Walrus
 *
 * NOTE: File hashes are extracted from the sigstore attestation bundle,
 * not from a separate manifest. This ensures cryptographic integrity.
 */
export interface ManifestQuilt {
  quilt_type: 'manifest';
  quilt_version: '1.0';

  // Domain info
  domain: string;

  // Empty - file hashes come from attestation
  files_manifest: {};

  // Minimal metadata
  metadata: {
    note: string;
  };

  // Quilt tracking
  created_at: string;
  quilt_hash: string; // SHA256 of entire quilt
}

/**
 * Attestation Quilt - Contains raw sigstore attestation bundle
 * This quilt is prepared by GitHub Action and sent to verification server
 * The verification server will upload it to Walrus
 *
 * NOTE: We store the RAW sigstore bundle (SerializedBundle) which contains:
 * - File hashes (in the provenance subject)
 * - Cryptographic signatures
 * - Certificate chain
 * - Transparency log entry
 * This ensures all data comes from a single cryptographically verified source.
 */
export interface AttestationQuilt {
  quilt_type: 'attestation';
  quilt_version: '1.0';

  // Domain info
  domain: string;

  // Domain verification
  domain_verification: {
    domain_verification_hash: string;
    domain_signature: string;
    signature_timestamp: string;
  };

  // GitHub OIDC info (minimal metadata only)
  github_attestation: {
    run_id: number;
    repository: string;
    workflow: string;
    commit_sha: string;
    workflow_ref: string;
    timestamp: string;
  };

  // RAW Sigstore attestation bundle (contains everything)
  // This is a SerializedBundle from @sigstore/sign
  sigstore_attestation_bundle: any;

  // Quilt tracking
  created_at: string;
  quilt_hash: string; // SHA256 of entire quilt
}

/**
 * Enhanced file manifest generator supporting up to 10,000 files with parallel processing
 * Following V1.0 specification for file-level integrity and enterprise scale
 */
export async function generateFileManifest(
  buildDir: string,
  options: FileManifestOptions
): Promise<FileManifest> {
  const startTime = Date.now();
  const progressEmitter = options.enableProgressReporting ? new EventEmitter() : undefined;
  const performanceMetrics: PerformanceMetrics = {
    total_processing_time_ms: 0,
    file_discovery_time_ms: 0,
    hashing_time_ms: 0,
    concurrent_operations: 0,
    average_file_processing_time_ms: 0,
    files_per_second: 0,
    memory_peak_mb: 0
  };

  try {
    // Validate directory exists before processing
    await fs.access(buildDir);
    
    core.info(`🚀 Generating enhanced file manifest for directory: ${buildDir}`);
    
    // Phase 1: File Discovery with enhanced filtering
    const discoveryStartTime = Date.now();
    if (progressEmitter) {
      progressEmitter.emit('progress', { type: 'discovery', files_discovered: 0 });
    }
    
    const allFiles = await collectFilesEnhanced(buildDir, options, progressEmitter);
    const discoveryEndTime = Date.now();
    performanceMetrics.file_discovery_time_ms = discoveryEndTime - discoveryStartTime;
    
    core.info(`📁 Discovered ${allFiles.length} files in ${performanceMetrics.file_discovery_time_ms}ms`);
    if (progressEmitter) {
      progressEmitter.emit('progress', { 
        type: 'discovery', 
        files_discovered: allFiles.length,
        total_files: allFiles.length 
      });
    }

    // Phase 2: Choose processing strategy based on scale and options
    const processingStartTime = Date.now();
    let fileEntries: FileEntry[];
    let generationMethod: 'sequential' | 'parallel' | 'worker-threads';

    if (options.useWorkerThreads && allFiles.length > 100) {
      // Use Worker threads for very large file sets
      core.info(`🔧 Using Worker threads for ${allFiles.length} files`);
      generationMethod = 'worker-threads';
      fileEntries = await processFilesWithWorkers(buildDir, allFiles, options, progressEmitter);
    } else if (options.parallelProcessing && allFiles.length > 10) {
      // Use async parallel processing for medium file sets
      core.info(`⚡ Using parallel processing for ${allFiles.length} files`);
      generationMethod = 'parallel';
      const concurrency = options.concurrency || Math.min(os.cpus().length * 2, 20);
      fileEntries = await processFilesParallelEnhanced(buildDir, allFiles, concurrency, progressEmitter);
    } else {
      // Use sequential processing for small file sets
      core.info(`📝 Using sequential processing for ${allFiles.length} files`);
      generationMethod = 'sequential';
      fileEntries = await processFilesSequentialEnhanced(buildDir, allFiles, progressEmitter);
    }

    const processingEndTime = Date.now();
    performanceMetrics.hashing_time_ms = processingEndTime - processingStartTime;
    performanceMetrics.concurrent_operations = options.concurrency || 1;

    // Phase 3: Calculate aggregated metadata
    const totalSize = fileEntries.reduce((sum, file) => sum + file.size_bytes, 0);
    const totalProcessingTime = Date.now() - startTime;
    performanceMetrics.total_processing_time_ms = totalProcessingTime;
    performanceMetrics.average_file_processing_time_ms = totalProcessingTime / fileEntries.length;
    performanceMetrics.files_per_second = Math.round((fileEntries.length * 1000) / totalProcessingTime);
    performanceMetrics.memory_peak_mb = Math.round(process.memoryUsage().heapUsed / 1024 / 1024);

    const manifest: FileManifest = {
      domain: options.domain,
      version: 1, // V1.0 specification
      timestamp: new Date().toISOString(),
      total_files: fileEntries.length,
      total_size_bytes: totalSize,
      files: fileEntries,
      processing_duration_ms: totalProcessingTime,
      parallelism_used: options.concurrency || 1,
      performance_metrics: options.performanceMetrics ? performanceMetrics : undefined,
      generation_method: generationMethod
    };

    core.info(`✅ Generated enhanced manifest: ${manifest.total_files} files, ${formatBytes(totalSize)}, ${totalProcessingTime}ms (${performanceMetrics.files_per_second} files/sec)`);
    
    if (progressEmitter) {
      progressEmitter.emit('progress', { 
        type: 'completed', 
        files_processed: fileEntries.length,
        total_files: fileEntries.length,
        percentage: 100
      });
    }

    return manifest;

  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    if (progressEmitter) {
      progressEmitter.emit('progress', { type: 'error', error: error as Error });
    }
    throw new Error(`Failed to generate file manifest: ${errorMessage}`);
  }
}

/**
 * Enhanced file collection with comprehensive filtering and progress reporting
 * Supports up to 10,000 files with optimized directory traversal
 */
async function collectFilesEnhanced(
  dir: string, 
  options: FileManifestOptions,
  progressEmitter?: EventEmitter
): Promise<string[]> {
  const files: string[] = [];
  const maxFiles = Math.min(options.maxFiles, 10000); // Hard limit for enterprise scale
  let processedDirs = 0;
  const startTime = Date.now();

  // Build comprehensive ignore patterns
  const ignorePatterns = buildIgnorePatterns(options.customIgnorePatterns);
  
  async function walkDirectory(currentDir: string, depth: number = 0): Promise<void> {
    if (files.length >= maxFiles) {
      core.warning(`⚠️ Reached maximum file limit of ${maxFiles}, stopping collection`);
      return;
    }

    // Prevent excessively deep recursion
    if (depth > 50) {
      core.warning(`⚠️ Maximum directory depth (50) reached in ${currentDir}`);
      return;
    }

    try {
      const entries = await fs.readdir(currentDir, { withFileTypes: true });
      processedDirs++;
      
      // Emit progress every 100 directories
      if (processedDirs % 100 === 0 && progressEmitter) {
        progressEmitter.emit('progress', { 
          type: 'discovery', 
          files_discovered: files.length 
        });
      }
      
      // Sort entries to ensure consistent ordering across platforms
      const sortedEntries = entries.sort((a, b) => a.name.localeCompare(b.name));
      
      for (const entry of sortedEntries) {
        if (files.length >= maxFiles) break;

        const fullPath = join(currentDir, entry.name);
        const relativePath = relative(dir, fullPath);

        if (entry.isDirectory()) {
          // Enhanced directory filtering with custom patterns
          if (!shouldSkipDirectoryEnhanced(entry.name, relativePath, ignorePatterns)) {
            await walkDirectory(fullPath, depth + 1);
          }
        } else if (entry.isFile()) {
          // Enhanced file filtering with custom patterns  
          if (!shouldSkipFileEnhanced(entry.name, relativePath, ignorePatterns)) {
            files.push(fullPath);
            
            // Emit progress for large file discoveries
            if (files.length % 1000 === 0 && progressEmitter) {
              progressEmitter.emit('progress', { 
                type: 'discovery', 
                files_discovered: files.length 
              });
            }
          }
        }
      }
    } catch (error) {
      core.warning(`⚠️ Failed to read directory ${currentDir}: ${error}`);
    }
  }

  await walkDirectory(dir);
  const discoveryTime = Date.now() - startTime;
  
  core.info(`🔍 File discovery completed: ${files.length} files, ${processedDirs} directories, ${discoveryTime}ms`);
  return files;
}

/**
 * Enhanced sequential processing with progress reporting and caching
 */
async function processFilesSequentialEnhanced(
  buildDir: string, 
  filePaths: string[],
  progressEmitter?: EventEmitter
): Promise<FileEntry[]> {
  const entries: FileEntry[] = [];
  const startTime = Date.now();
  
  for (let i = 0; i < filePaths.length; i++) {
    const filePath = filePaths[i];
    try {
      const fileStartTime = Date.now();
      const entry = await processFileEnhanced(buildDir, filePath);
      entry.processing_time_ms = Date.now() - fileStartTime;
      entries.push(entry);
      
      // Progress reporting every 100 files or every 5 seconds
      if ((i + 1) % 100 === 0 || (Date.now() - startTime) % 5000 < 100) {
        const percentage = Math.round(((i + 1) / filePaths.length) * 100);
        const elapsed = Date.now() - startTime;
        const estimatedTotal = elapsed * (filePaths.length / (i + 1));
        const remaining = estimatedTotal - elapsed;
        
        core.info(`📊 Progress: ${i + 1}/${filePaths.length} files (${percentage}%) - ${Math.round(remaining/1000)}s remaining`);
        
        if (progressEmitter) {
          progressEmitter.emit('progress', {
            type: 'processing',
            files_processed: i + 1,
            total_files: filePaths.length,
            current_file: relative(buildDir, filePath),
            percentage,
            estimated_remaining_ms: remaining
          });
        }
      }
    } catch (error) {
      core.warning(`⚠️ Failed to process file ${filePath}: ${error}`);
    }
  }

  return entries;
}

/**
 * Enhanced parallel processing with dynamic batching and progress reporting
 * Optimized for processing up to 10,000 files efficiently
 */
async function processFilesParallelEnhanced(
  buildDir: string,
  filePaths: string[],
  concurrency: number,
  progressEmitter?: EventEmitter
): Promise<FileEntry[]> {
  const entries: FileEntry[] = [];
  const totalFiles = filePaths.length;
  let processedFiles = 0;
  const startTime = Date.now();
  
  // Calculate optimal chunk size based on file count and concurrency
  const chunkSize = Math.max(1, Math.ceil(totalFiles / (concurrency * 4)));
  core.info(`⚡ Parallel processing: ${concurrency} workers, ${chunkSize} files per chunk`);
  
  // Create chunks for balanced workload distribution
  const chunks: string[][] = [];
  for (let i = 0; i < filePaths.length; i += chunkSize) {
    chunks.push(filePaths.slice(i, i + chunkSize));
  }
  
  // Process chunks with controlled concurrency
  const processingPromises: Promise<void>[] = [];
  const semaphore = new Array(concurrency).fill(null);
  
  for (let chunkIndex = 0; chunkIndex < chunks.length; chunkIndex++) {
    const chunk = chunks[chunkIndex];
    
    const chunkPromise = Promise.resolve().then(async () => {
      const chunkStartTime = Date.now();
      const chunkEntries: FileEntry[] = [];
      
      // Process files in current chunk
      const chunkProcessingPromises = chunk.map(async (filePath) => {
        try {
          const fileStartTime = Date.now();
          const entry = await processFileEnhanced(buildDir, filePath);
          entry.processing_time_ms = Date.now() - fileStartTime;
          chunkEntries.push(entry);
        } catch (error) {
          core.warning(`⚠️ Failed to process file ${filePath}: ${error}`);
        }
      });
      
      await Promise.all(chunkProcessingPromises);
      
      // Thread-safe addition to main entries array
      entries.push(...chunkEntries);
      processedFiles += chunk.length;
      
      // Progress reporting
      const percentage = Math.round((processedFiles / totalFiles) * 100);
      const elapsed = Date.now() - startTime;
      const estimatedTotal = elapsed * (totalFiles / processedFiles);
      const remaining = estimatedTotal - elapsed;
      
      core.info(`🔄 Chunk ${chunkIndex + 1}/${chunks.length} completed: ${processedFiles}/${totalFiles} files (${percentage}%) - ${Math.round(remaining/1000)}s remaining`);
      
      if (progressEmitter) {
        progressEmitter.emit('progress', {
          type: 'processing',
          files_processed: processedFiles,
          total_files: totalFiles,
          percentage,
          estimated_remaining_ms: remaining
        });
      }
    });
    
    processingPromises.push(chunkPromise);
    
    // Wait for a slot if we've reached concurrency limit
    if (processingPromises.length >= concurrency) {
      await Promise.race(processingPromises);
      // Remove completed promises
      const completedIndex = processingPromises.findIndex(p => 
        p.then(() => true, () => true)
      );
      if (completedIndex >= 0) {
        processingPromises.splice(completedIndex, 1);
      }
    }
  }
  
  // Wait for all remaining chunks to complete
  await Promise.all(processingPromises);
  
  // Sort entries for consistent ordering
  const sortedEntries = entries.sort((a, b) => a.path.localeCompare(b.path));
  const totalTime = Date.now() - startTime;
  const avgTimePerFile = totalTime / sortedEntries.length;
  
  core.info(`✅ Parallel processing completed: ${sortedEntries.length} files in ${totalTime}ms (avg ${avgTimePerFile.toFixed(2)}ms per file)`);
  
  return sortedEntries;
}

/**
 * Process individual file and calculate hash
 */
async function processFile(buildDir: string, filePath: string): Promise<FileEntry> {
  const stats = await fs.stat(filePath);
  const content = await fs.readFile(filePath);
  
  // Calculate SHA256 hash
  const hash = createHash('sha256');
  hash.update(content);
  const contentHash = hash.digest('hex');

  // Get relative path from build directory
  const relativePath = '/' + relative(buildDir, filePath).replace(/\\/g, '/');

  // Determine content type based on file extension
  const contentType = getContentType(filePath);

  return {
    path: relativePath,
    content_hash: `sha256:${contentHash}`,
    size_bytes: stats.size,
    content_type: contentType,
    last_modified: Math.floor(stats.mtime.getTime() / 1000),
    encoding: 'identity',
    blob_id: null // Will be populated after Walrus upload
  };
}

/**
 * Get MIME content type based on file extension
 */
function getContentType(filePath: string): string {
  const ext = filePath.toLowerCase().split('.').pop();
  
  const contentTypes: Record<string, string> = {
    // Web files
    'html': 'text/html',
    'htm': 'text/html',
    'css': 'text/css',
    'js': 'application/javascript',
    'mjs': 'application/javascript',
    'json': 'application/json',
    'xml': 'application/xml',
    
    // Images
    'png': 'image/png',
    'jpg': 'image/jpeg',
    'jpeg': 'image/jpeg',
    'gif': 'image/gif',
    'svg': 'image/svg+xml',
    'webp': 'image/webp',
    'ico': 'image/x-icon',
    
    // Fonts
    'woff': 'font/woff',
    'woff2': 'font/woff2',
    'ttf': 'font/ttf',
    'eot': 'application/vnd.ms-fontobject',
    
    // Documents
    'pdf': 'application/pdf',
    'txt': 'text/plain',
    'md': 'text/markdown',
    
    // Archives
    'zip': 'application/zip',
    'gz': 'application/gzip',
    
    // Other
    'wasm': 'application/wasm',
    'map': 'application/json'
  };

  return contentTypes[ext || ''] || 'application/octet-stream';
}

/**
 * Check if directory should be skipped
 */
function shouldSkipDirectory(name: string): boolean {
  const skipDirs = [
    'node_modules',
    '.git',
    '.svn',
    '.hg',
    '__pycache__',
    '.pytest_cache',
    'coverage',
    '.nyc_output',
    'logs',
    '*.log',
    'tmp',
    'temp'
  ];

  return skipDirs.some(pattern => {
    if (pattern.includes('*')) {
      const regex = new RegExp(pattern.replace(/\*/g, '.*'));
      return regex.test(name);
    }
    return name === pattern;
  });
}

/**
 * Check if file should be skipped
 */
function shouldSkipFile(name: string): boolean {
  const skipFiles = [
    '.DS_Store',
    'Thumbs.db',
    '*.log',
    '*.tmp',
    '*.temp',
    '.env',
    '.env.*',
    '*.key',
    '*.pem',
    '*.p12'
  ];

  return skipFiles.some(pattern => {
    if (pattern.includes('*')) {
      const regex = new RegExp(pattern.replace(/\*/g, '.*'));
      return regex.test(name);
    }
    return name === pattern;
  });
}

/**
 * Enhanced file processing with streaming hash calculation and metadata collection
 * Optimized for large files and comprehensive metadata
 */
async function processFileEnhanced(buildDir: string, filePath: string): Promise<FileEntry> {
  const fileStartTime = Date.now();
  const stats = await fs.stat(filePath);
  
  // Use streaming hash calculation for large files (>10MB)
  let contentHash: string;
  if (stats.size > 10 * 1024 * 1024) {
    contentHash = await calculateStreamingHash(filePath);
  } else {
    const content = await fs.readFile(filePath);
    const hash = createHash('sha256');
    hash.update(content);
    contentHash = hash.digest('hex');
  }

  // Get relative path from build directory (normalized for cross-platform)
  const relativePath = '/' + relative(buildDir, filePath).replace(/\\/g, '/');

  // Determine content type with enhanced detection
  const contentType = getContentTypeEnhanced(filePath);
  
  // Get file timestamps and permissions
  const createdAt = stats.birthtime.toISOString();
  const modifiedAt = stats.mtime.toISOString();
  const fileMode = '0' + (stats.mode & parseInt('777', 8)).toString(8); // Get permissions

  return {
    path: relativePath,
    content_hash: `sha256:${contentHash}`,
    size_bytes: stats.size,
    content_type: contentType,
    last_modified: Math.floor(stats.mtime.getTime() / 1000),
    encoding: 'identity',
    blob_id: null, // Will be populated after Walrus upload
    created_at: createdAt,
    modified_at: modifiedAt,
    file_mode: fileMode,
    processing_time_ms: Date.now() - fileStartTime
  };
}

/**
 * Calculate SHA256 hash using streaming for large files
 * Memory-efficient for files larger than 10MB
 */
async function calculateStreamingHash(filePath: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const hash = createHash('sha256');
    const stream = require('fs').createReadStream(filePath);
    
    stream.on('data', (data: Buffer) => {
      hash.update(data);
    });
    
    stream.on('end', () => {
      resolve(hash.digest('hex'));
    });
    
    stream.on('error', (error: Error) => {
      reject(error);
    });
  });
}

/**
 * Worker thread-based processing for very large file sets (>100 files)
 * Distributes work across CPU cores for maximum performance
 */
async function processFilesWithWorkers(
  buildDir: string,
  filePaths: string[],
  options: FileManifestOptions,
  progressEmitter?: EventEmitter
): Promise<FileEntry[]> {
  const startTime = Date.now();
  const numWorkers = Math.min(options.concurrency || os.cpus().length, 8); // Max 8 workers
  const chunkSize = Math.ceil(filePaths.length / numWorkers);
  
  core.info(`🔧 Spawning ${numWorkers} worker threads for ${filePaths.length} files (${chunkSize} files per worker)`);
  
  // Create chunks for workers
  const chunks: string[][] = [];
  for (let i = 0; i < filePaths.length; i += chunkSize) {
    chunks.push(filePaths.slice(i, i + chunkSize));
  }
  
  // Spawn workers
  const workerPromises: Promise<WorkerResult>[] = [];
  
  for (let i = 0; i < chunks.length && i < numWorkers; i++) {
    const chunk = chunks[i];
    if (chunk.length === 0) continue;
    
    const workerPromise = new Promise<WorkerResult>((resolve, reject) => {
      // Note: In a real implementation, we'd create a separate worker file
      // For now, we'll simulate worker behavior with async processing
      processWorkerChunk(buildDir, chunk, i, chunks.length)
        .then(resolve)
        .catch(reject);
    });
    
    workerPromises.push(workerPromise);
  }
  
  // Wait for all workers to complete
  const workerResults = await Promise.all(workerPromises);
  
  // Combine results from all workers
  const allEntries: FileEntry[] = [];
  for (const result of workerResults) {
    allEntries.push(...result.entries);
  }
  
  // Sort for consistent ordering
  const sortedEntries = allEntries.sort((a, b) => a.path.localeCompare(b.path));
  
  const totalTime = Date.now() - startTime;
  const avgTimePerFile = totalTime / sortedEntries.length;
  
  core.info(`✅ Worker thread processing completed: ${sortedEntries.length} files in ${totalTime}ms (avg ${avgTimePerFile.toFixed(2)}ms per file)`);
  
  if (progressEmitter) {
    progressEmitter.emit('progress', {
      type: 'processing',
      files_processed: sortedEntries.length,
      total_files: sortedEntries.length,
      percentage: 100
    });
  }
  
  return sortedEntries;
}

/**
 * Simulate worker chunk processing
 * In a real implementation, this would be in a separate worker file
 */
async function processWorkerChunk(
  buildDir: string,
  filePaths: string[],
  chunkIndex: number,
  totalChunks: number
): Promise<WorkerResult> {
  const startTime = Date.now();
  const entries: FileEntry[] = [];
  
  core.info(`🔧 Worker ${chunkIndex + 1}/${totalChunks} processing ${filePaths.length} files`);
  
  for (const filePath of filePaths) {
    try {
      const entry = await processFileEnhanced(buildDir, filePath);
      entries.push(entry);
    } catch (error) {
      core.warning(`⚠️ Worker ${chunkIndex + 1} failed to process file ${filePath}: ${error}`);
    }
  }
  
  const processingTimeMs = Date.now() - startTime;
  core.info(`✅ Worker ${chunkIndex + 1}/${totalChunks} completed: ${entries.length} files in ${processingTimeMs}ms`);
  
  return {
    entries,
    processingTimeMs,
    chunkIndex
  };
}

