/**
 * Build comprehensive ignore patterns from defaults and custom patterns
 */
function buildIgnorePatterns(customPatterns?: string[]): RegExp[] {
  const defaultPatterns = [
    // Version control
    '\\.git',
    '\\.svn',
    '\\.hg',
    '\\.bzr',
    '_darcs',
    
    // Dependencies
    'node_modules',
    'bower_components',
    'jspm_packages',
    'vendor',
    
    // Build outputs
    'dist',
    'build',
    'out',
    'target',
    '^bin$',
    'obj',
    
    // Cache directories
    '\\.cache',
    '\\.npm',
    '\\.yarn',
    '\\.pnpm-store',
    '__pycache__',
    '\\.pytest_cache',
    'coverage',
    '\\.nyc_output',
    '\\.next',
    '\\.nuxt',
    '\\.vuepress',
    
    // IDE and editor files
    '\\.vscode',
    '\\.idea',
    '\\.eclipse',
    '\\.settings',
    
    // OS files
    '\\.DS_Store',
    'Thumbs\\.db',
    'desktop\\.ini',
    
    // Logs and temporary files
    '^logs?$',
    '.*\\.log',
    '^tmp$',
    '^temp$',
    '.*\\.tmp',
    '.*\\.temp'
  ];
  
  const allPatterns = [...defaultPatterns, ...(customPatterns || [])];
  return allPatterns.map(pattern => new RegExp(pattern, 'i'));
}

/**
 * Enhanced directory filtering with custom patterns and relative path support
 */
function shouldSkipDirectoryEnhanced(
  name: string, 
  relativePath: string, 
  ignorePatterns: RegExp[]
): boolean {
  // Test against all ignore patterns
  return ignorePatterns.some(pattern => 
    pattern.test(name) || pattern.test(relativePath)
  );
}

/**
 * Enhanced file filtering with custom patterns and security considerations
 */
function shouldSkipFileEnhanced(
  name: string, 
  relativePath: string, 
  ignorePatterns: RegExp[]
): boolean {
  const securitySensitivePatterns = [
    // Environment and config files
    /\.env(\..*)?$/,
    /\.config$/,
    /config\.json$/,
    /secrets?\./,
    
    // Security files
    /.*\.(key|pem|p12|pfx|crt|cert|csr)$/,
    /private.*key/,
    /.*\.ssh\/.*$/,
    
    // System files
    /\.DS_Store$/,
    /Thumbs\.db$/,
    /desktop\.ini$/,
    
    // Temporary and backup files
    /.*\.(log|tmp|temp|bak|backup|swp|swo)$/,
    /~.*$/,
    /.*~$/,
    
    // Lock files (unless specifically included)
    /.*\.(lock|lockb)$/,
    /package-lock\.json$/,
    /yarn\.lock$/,
    /composer\.lock$/,
    /Pipfile\.lock$/,
    
    // Source control files
    /\.gitignore$/,
    /\.gitattributes$/,
    /\.gitmodules$/
  ];
  
  // Check security sensitive patterns first
  const isSecuritySensitive = securitySensitivePatterns.some(pattern => 
    pattern.test(name) || pattern.test(relativePath)
  );
  
  if (isSecuritySensitive) {
    return true;
  }
  
  // Check custom ignore patterns
  return ignorePatterns.some(pattern => 
    pattern.test(name) || pattern.test(relativePath)
  );
}

/**
 * Format bytes in human-readable format
 */
function formatBytes(bytes: number): string {
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let size = bytes;
  let unitIndex = 0;
  
  while (size >= 1024 && unitIndex < units.length - 1) {
    size /= 1024;
    unitIndex++;
  }
  
  return `${size.toFixed(1)}${units[unitIndex]}`;
}

/**
 * Create progress reporter for file manifest generation
 * Returns EventEmitter that can be used to track progress
 */
export function createProgressReporter(): EventEmitter {
  const emitter = new EventEmitter();
  
  emitter.on('progress', (event: ProgressEvent) => {
    switch (event.type) {
      case 'discovery':
        if (event.files_discovered) {
          core.info(`🔍 Discovery: Found ${event.files_discovered} files`);
        }
        break;
        
      case 'processing':
        if (event.percentage && event.estimated_remaining_ms) {
          const remainingSeconds = Math.round(event.estimated_remaining_ms / 1000);
          core.info(`📊 Processing: ${event.percentage}% complete, ~${remainingSeconds}s remaining`);
        }
        break;
        
      case 'completed':
        core.info(`✅ Completed: ${event.files_processed} files processed successfully`);
        break;
        
      case 'error':
        core.error(`❌ Error: ${event.error?.message}`);
        break;
    }
  });
  
  return emitter;
}

/**
 * Build manifest quilt - now returns EMPTY structure
 * File hashes are extracted from the sigstore attestation bundle instead
 * The quilt is prepared as JSON and sent to verification server
 * The verification server will upload it to Walrus
 */
export function buildManifestQuilt(
  domain: string,
  filesManifest: FileManifest,
  metadata: {
    buildTimestamp: string;
    githubRepo: string;
    commitSha: string;
    workflowRef: string;
    deploymentTarget: string;
  }
): ManifestQuilt {
  const quilt: Omit<ManifestQuilt, 'quilt_hash'> = {
    quilt_type: MANIFEST_QUILT_TYPE as 'manifest',
    quilt_version: QUILT_VERSION as '1.0',
    domain,
    files_manifest: {},  // EMPTY - file hashes come from attestation
    metadata: {
      note: 'File hashes are extracted from sigstore attestation bundle'
    },
    created_at: new Date().toISOString(),
  };

  // Calculate quilt hash
  const quiltJson = JSON.stringify(quilt);
  const hash = createHash('sha256').update(quiltJson).digest('hex');

  return {
    ...quilt,
    quilt_hash: `sha256:${hash}`,
  };
}

/**
 * Build attestation quilt with RAW sigstore bundle
 * The quilt is prepared as JSON and sent to verification server
 * The verification server will upload it to Walrus
 *
 * IMPORTANT: We now store the RAW sigstore bundle (SerializedBundle) which contains:
 * - File hashes in the provenance subject
 * - SLSA provenance data
 * - Cryptographic signatures and certificates
 * This ensures single source of truth from sigstore.
 */
export function buildAttestationQuilt(
  domain: string,
  domainVerification: {
    domainVerificationHash: string;
    domainSignature: string;
  },
  githubContext: {
    run_id: number;
    repository: string;
    workflow: string;
    commit_sha: string;
    workflow_ref: string;
  },
  rawSigstoreBundle: any  // This is the SerializedBundle from @sigstore/sign
): AttestationQuilt {
  const quilt: Omit<AttestationQuilt, 'quilt_hash'> = {
    quilt_type: ATTESTATION_QUILT_TYPE as 'attestation',
    quilt_version: QUILT_VERSION as '1.0',
    domain,
    domain_verification: {
      domain_verification_hash: domainVerification.domainVerificationHash,
      domain_signature: domainVerification.domainSignature,
      signature_timestamp: new Date().toISOString(),
    },
    github_attestation: {
      run_id: githubContext.run_id,
      repository: githubContext.repository,
      workflow: githubContext.workflow,
      commit_sha: githubContext.commit_sha,
      workflow_ref: githubContext.workflow_ref,
      timestamp: new Date().toISOString(),
    },
    sigstore_attestation_bundle: rawSigstoreBundle,  // RAW bundle with everything
    created_at: new Date().toISOString(),
  };

  // Calculate quilt hash
  const quiltJson = JSON.stringify(quilt);
  const hash = createHash('sha256').update(quiltJson).digest('hex');

  return {
    ...quilt,
    quilt_hash: `sha256:${hash}`,
  };
}

/**
 * Validate quilt structure before sending to server
 * Checks required fields and size limits
 */
export function validateQuilt(quilt: ManifestQuilt | AttestationQuilt): void {
  if (!quilt || typeof quilt !== 'object') {
    throw new Error('Invalid quilt: not an object');
  }

  if (!quilt.quilt_type || !quilt.quilt_version) {
    throw new Error('Invalid quilt: missing quilt_type or quilt_version');
  }

  if (quilt.quilt_version !== QUILT_VERSION) {
    throw new Error(`Unsupported quilt version: ${quilt.quilt_version}`);
  }

  const quiltType = quilt.quilt_type;
  if (quiltType !== MANIFEST_QUILT_TYPE && quiltType !== ATTESTATION_QUILT_TYPE) {
    throw new Error(`Invalid quilt type: ${quiltType}`);
  }

  if (!quilt.domain || !quilt.created_at || !quilt.quilt_hash) {
    throw new Error('Invalid quilt: missing required fields (domain, created_at, quilt_hash)');
  }

  // Validate size
  const quiltJson = JSON.stringify(quilt);
  const quiltSizeBytes = Buffer.byteLength(quiltJson, 'utf8');

  if (quilt.quilt_type === MANIFEST_QUILT_TYPE && quiltSizeBytes > 50 * 1024 * 1024) {
    throw new Error(
      `Manifest quilt too large: ${(quiltSizeBytes / 1024 / 1024).toFixed(1)}MB (max 50MB)`
    );
  }

  if (quilt.quilt_type === ATTESTATION_QUILT_TYPE && quiltSizeBytes > 10 * 1024 * 1024) {
    throw new Error(
      `Attestation quilt too large: ${(quiltSizeBytes / 1024 / 1024).toFixed(1)}MB (max 10MB)`
    );
  }
}