import * as core from '@actions/core';
import { SuiClient, SuiTransactionBlockResponse } from '@mysten/sui/client';
import { Ed25519Keypair } from '@mysten/sui/keypairs/ed25519';
import { Transaction } from '@mysten/sui/transactions';
import { fromBase64 } from '@mysten/sui/utils';

// TEE Attestation types for new attestation flow (Phase 2 - TEE Integration Plan)
import type {
  TEEAttestationProof,
  TEEAttestationSubmissionResult,
  TEEAttestationConfig,
} from './types/tee-attestation';
import {
  serializeAttestationProof,
  type SerializedAttestationProof,
} from './utils/attestation-serializer';

/**
 * Configuration for Sui client
 */
export interface SuiClientConfig {
  rpcUrl: string;
  network: 'testnet' | 'mainnet' | 'localnet';
  packageId?: string;
  registryId: string;
  gasBudget?: string;
}

/**
 * Domain record information from blockchain
 */
export interface DomainRecord {
  id: string;
  domain: string;
  owner: string;
  currentVersion: bigint;
}

/**
 * Result of a Sui transaction
 */
export interface TransactionResult {
  digest: string;
  status: 'success' | 'failure';
  newVersion?: string;
  gasUsed?: number;
  error?: string;
}

/**
 * Error thrown by Sui operations
 */
export class SuiError extends Error {
  constructor(
    message: string,
    public code: string,
    public details?: any
  ) {
    super(message);
    this.name = 'SuiError';
  }
}

/**
 * Client for interacting with Sui blockchain
 * Handles domain lookups and site data updates
 */
export class CryptoGuardSuiClient {
  private readonly client: SuiClient;
  private readonly network: string;
  private readonly packageId: string;
  private readonly registryId: string;
  private readonly gasBudget: bigint;

  constructor(config: SuiClientConfig) {
    this.client = new SuiClient({ url: config.rpcUrl });
    this.network = config.network;
    this.packageId = config.packageId || this.getDefaultPackageId(config.network);
    this.registryId = config.registryId;
    this.gasBudget = BigInt(config.gasBudget || '10000000'); // 0.01 SUI default
  }

  /**
   * Get default package ID for network
   */
  private getDefaultPackageId(network: string): string {
    // Production contract IDs deployed on each network - Updated 2025-12-22 (v3)
    const packageIds: Record<string, string> = {
      testnet: process.env.SUI_PACKAGE_ID_TESTNET || '0x3060269697cf05189ee720c877f672ea80de5152bdccabb30c5fff50f007a5d8',
      mainnet: process.env.SUI_PACKAGE_ID_MAINNET || '0x0', // Not deployed yet
      localnet: process.env.SUI_PACKAGE_ID_LOCALNET || '0x0', // For local development
    };
    return packageIds[network] || '0x0';
  }

  /**
   * Look up a domain's SiteRecord by domain name
   * @param domain - Domain name to look up
   * @returns Domain record information or null if not found
   */
  async lookupDomain(domain: string): Promise<DomainRecord | null> {
    try {
      core.debug(`Looking up domain: ${domain}`);

      // Step 1: Get the registry object to find domain_name_index table ID
      const registryObject = await this.client.getObject({
        id: this.registryId,
        options: { showContent: true },
      });

      if (!registryObject.data?.content || registryObject.data.content.dataType !== 'moveObject') {
        throw new SuiError('Registry object not found or invalid', 'REGISTRY_NOT_FOUND', { registryId: this.registryId });
      }

      const registryFields = (registryObject.data.content as any).fields;
      const domainNameIndexId = registryFields.domain_name_index?.fields?.id?.id;

      if (!domainNameIndexId) {
        throw new SuiError('domain_name_index table not found in registry', 'REGISTRY_INVALID', { registryId: this.registryId });
      }

      core.debug(`Found domain_name_index table: ${domainNameIndexId}`);

      // Step 2: Query the domain_name_index table for the domain
      // The table uses String keys, so we need to use getDynamicFieldObject
      const domainLookup = await this.client.getDynamicFieldObject({
        parentId: domainNameIndexId,
        name: {
          type: '0x1::string::String',
          value: domain,
        },
      });

      if (!domainLookup.data?.content || domainLookup.data.content.dataType !== 'moveObject') {
        core.debug(`No SiteRecord found for domain: ${domain}`);
        return null;
      }

      // The value in the table is the SiteRecord object ID
      const siteRecordId = (domainLookup.data.content as any).fields?.value;

      if (!siteRecordId) {
        core.debug(`Domain found but SiteRecord ID is missing: ${domain}`);
        return null;
      }

      core.debug(`Found SiteRecord ID for domain ${domain}: ${siteRecordId}`);

      // Step 3: Get the actual SiteRecord object
      const siteRecordObject = await this.client.getObject({
        id: siteRecordId,
        options: {
          showContent: true,
          showOwner: true,
        },
      });

      if (!siteRecordObject.data?.content || siteRecordObject.data.content.dataType !== 'moveObject') {
        core.debug(`SiteRecord object not found: ${siteRecordId}`);
        return null;
      }

      const fields = (siteRecordObject.data.content as any).fields;

      return {
        id: siteRecordId,
        domain: fields.domain,
        owner: fields.owner || 'unknown',
        currentVersion: BigInt(fields.current_version || 0),
      };

    } catch (error) {
      if (error instanceof SuiError) {
        throw error;
      }
      throw new SuiError(
        `Failed to lookup domain: ${error instanceof Error ? error.message : String(error)}`,
        'DOMAIN_LOOKUP_FAILED',
        { domain, error: error instanceof Error ? error.message : String(error) }
      );
    }
  }

  /**
   * Build and submit update_site_data transaction
   * @param privateKey - User's private key (hex string with or without 0x prefix)
   * @param siteRecordId - SiteRecord object ID
   * @param filesManifest - Files manifest
   * @param deploymentMetadata - Deployment metadata from TEE verification
   * @returns Transaction result
   */
  async updateSiteData(
    privateKey: string,
    siteRecordId: string,
    filesManifest: any,
    deploymentMetadata: {
      provenance_blob_id: string;
      content_quilt_id?: string;
      metadata_quilt_id?: string;
      github_commit_sha: string;
      slsa_level: string;
      build_timestamp: number;
      github_repo: string;
      workflow_ref: string;
      deployment_target: string;
    }
  ): Promise<TransactionResult> {
    try {
      // Parse private key and get user address
      const keypair = this.parsePrivateKey(privateKey);
      const userAddress = keypair.getPublicKey().toSuiAddress();

      core.debug(`User address: ${userAddress}`);

      // Verify user owns the SiteRecord
      const siteRecord = await this.client.getObject({
        id: siteRecordId,
        options: { showOwner: true, showContent: true },
      });

      if (!siteRecord.data) {
        throw new SuiError(
          `SiteRecord ${siteRecordId} not found`,
          'SITE_RECORD_NOT_FOUND',
          { siteRecordId }
        );
      }

      // Check ownership
      const owner = (siteRecord.data.owner as any)?.AddressOwner || (siteRecord.data.owner as any)?.ObjectOwner;
      if (owner !== userAddress) {
        throw new SuiError(
          `SiteRecord owned by ${owner}, signed by ${userAddress}`,
          'UNAUTHORIZED',
          { owner, signer: userAddress }
        );
      }

      // Build transaction
      const tx = new Transaction();
      tx.setGasBudget(this.gasBudget);

      // Prepare file manifest data
      const filePaths = filesManifest.files.map((f: any) => f.path);
      const fileHashes = filesManifest.files.map((f: any) => Array.from(Buffer.from(f.content_hash, 'hex')));
      const fileSizes = filesManifest.files.map((f: any) => f.size_bytes);
      const fileTypes = filesManifest.files.map((f: any) => f.content_type || 'application/octet-stream');
      const fileModifiedTimes = filesManifest.files.map((f: any) => f.last_modified || Date.now());
      const fileEncodings = filesManifest.files.map((f: any) => f.encoding || 'utf-8');

      core.debug(`Building update_site_data tx with ${filePaths.length} files`);

      // Call update_site_data function
      tx.moveCall({
        target: `${this.packageId}::domain_registry::update_site_data`,
        arguments: [
          tx.object(this.registryId),
          tx.object(siteRecordId),
          tx.pure.vector('string', filePaths),
          tx.pure.vector('vector<u8>', fileHashes),
          tx.pure.vector('u64', fileSizes),
          tx.pure.vector('string', fileTypes),
          tx.pure.vector('u64', fileModifiedTimes),
          tx.pure.vector('string', fileEncodings),
          tx.pure.string(deploymentMetadata.provenance_blob_id),
          tx.pure.u64(deploymentMetadata.build_timestamp),
          tx.pure.string(deploymentMetadata.slsa_level),
          tx.pure.string(deploymentMetadata.github_repo),
          tx.pure.string(deploymentMetadata.github_commit_sha),
          tx.pure.string(deploymentMetadata.workflow_ref),
          tx.pure.string(deploymentMetadata.deployment_target),
          tx.object('0x6'), // Clock object
        ],
      });

      // Sign and execute transaction
      const result = await this.client.signAndExecuteTransaction({
        transaction: tx,
        signer: keypair,
        options: {
          showEffects: true,
          showEvents: true,
          showObjectChanges: true,
        },
      });

      core.debug(`Transaction submitted: ${result.digest}`);

      // Check transaction status
      if (result.effects?.status?.status !== 'success') {
        const error = result.effects?.status?.error || 'Unknown error';
        throw new SuiError(
          `Transaction failed: ${error}`,
          'TRANSACTION_FAILED',
          { digest: result.digest, error }
        );
      }

      // Extract new version from events
      let newVersion = '0';
      if (result.events) {
        const updateEvent = result.events.find((e: any) =>
          e.type.includes('::domain_registry::SiteDataUpdated')
        );
        if (updateEvent && updateEvent.parsedJson) {
          const parsedJson = updateEvent.parsedJson as Record<string, any>;
          newVersion = String(parsedJson.version || parsedJson.new_version || '0');
        }
      }

      // Calculate gas used
      const gasUsed = result.effects?.gasUsed
        ? Number(result.effects.gasUsed.computationCost) + Number(result.effects.gasUsed.storageCost)
        : 0;

      core.debug(`Transaction confirmed: version=${newVersion}, gas=${gasUsed} MIST`);

      return {
        digest: result.digest,
        status: 'success',
        newVersion,
        gasUsed,
      };

    } catch (error) {
      if (error instanceof SuiError) {
        throw error;
      }

      const errorMessage = error instanceof Error ? error.message : String(error);

      // Parse common error types
      if (errorMessage.includes('Insufficient gas')) {
        throw new SuiError(
          'Insufficient SUI tokens in wallet for gas fees',
          'INSUFFICIENT_GAS',
          { error: errorMessage }
        );
      } else if (errorMessage.includes('Version mismatch') || errorMessage.includes('object version')) {
        throw new SuiError(
          'Concurrent deployment detected - SiteRecord version mismatch',
          'VERSION_CONFLICT',
          { error: errorMessage }
        );
      } else if (errorMessage.includes('not found')) {
        throw new SuiError(
          'SiteRecord not found on blockchain',
          'SITE_RECORD_NOT_FOUND',
          { error: errorMessage }
        );
      }

      throw new SuiError(
        `Transaction failed: ${errorMessage}`,
        'TRANSACTION_ERROR',
        { error: errorMessage }
      );
    }
  }

  /**
   * Parse private key from various formats
   * Supports: hex string (with or without 0x prefix), base64 bech32, etc.
   */
  private parsePrivateKey(privateKey: string): Ed25519Keypair {
    try {
      // Remove whitespace
      const key = privateKey.trim();

      // Try hex format (with or without 0x prefix)
      if (key.startsWith('0x') || key.startsWith('0X')) {
        const hexKey = key.substring(2);
        if (hexKey.length === 64) {
          // 32-byte private key
          const secretKey = Uint8Array.from(Buffer.from(hexKey, 'hex'));
          return Ed25519Keypair.fromSecretKey(secretKey);
        }
      }

      // Try raw hex without prefix
      if (/^[0-9a-fA-F]{64}$/.test(key)) {
        const secretKey = Uint8Array.from(Buffer.from(key, 'hex'));
        return Ed25519Keypair.fromSecretKey(secretKey);
      }

      // Try base64 format
      try {
        const decoded = fromBase64(key);
        if (decoded.length === 32 || decoded.length === 64) {
          return Ed25519Keypair.fromSecretKey(decoded.slice(0, 32));
        }
      } catch {
        // Not base64, continue
      }

      // Try Sui wallet export format (suiprivkey1...)
      if (key.startsWith('suiprivkey')) {
        // This would need bech32 decoding - for now throw error
        throw new Error('Bech32 private key format not yet supported. Please use hex format.');
      }

      throw new Error('Invalid private key format');

    } catch (error) {
      throw new SuiError(
        `Failed to parse private key: ${error instanceof Error ? error.message : String(error)}`,
        'INVALID_PRIVATE_KEY',
        { error: error instanceof Error ? error.message : String(error) }
      );
    }
  }

  /**
   * Get user's SUI balance
   * @param address - User's Sui address
   * @returns Balance in MIST
   */
  async getBalance(address: string): Promise<bigint> {
    try {
      const balance = await this.client.getBalance({
        owner: address,
      });
      return BigInt(balance.totalBalance);
    } catch (error) {
      throw new SuiError(
        `Failed to get balance: ${error instanceof Error ? error.message : String(error)}`,
        'BALANCE_CHECK_FAILED',
        { address, error: error instanceof Error ? error.message : String(error) }
      );
    }
  }

  // ============================================================================
  // TEE Attestation Methods (Phase 2 - TEE Integration Plan, Step 2.3)
  // ============================================================================

  /**
   * Update site data using TEE attestation.
   * The smart contract will verify the TEE attestation before updating.
   *
   * This is the new TEE attestation flow where:
   * 1. The action requests attestation from the TEE server
   * 2. The action submits the attestation to the smart contract
   * 3. The smart contract verifies the attestation using Nautilus library
   * 4. The smart contract updates the site record only after successful verification
   *
   * @param privateKey - Owner's private key for transaction signing (hex or base64)
   * @param siteRecordId - Sui object ID of the site record
   * @param attestation - TEE attestation proof from the TEE server
   * @param config - Optional configuration for attestation verification
   * @returns Transaction result with on-chain verification details
   * @throws SuiError if the transaction fails
   *
   * @example
   * ```typescript
   * const result = await suiClient.updateSiteWithTEEAttestation(
   *   '0x...private_key',
   *   '0x...site_record_id',
   *   attestationFromTEEServer,
   *   { maxAttestationAge: 300 }
   * );
   *
   * if (result.success) {
   *   console.log(`Updated to version ${result.newVersion}`);
   * }
   * ```
   *
   * @see TEE_ATTESTATION_INTEGRATION_PLAN.md - Phase 2, Step 2.3
   */
  async updateSiteWithTEEAttestation(
    privateKey: string,
    siteRecordId: string,
    attestation: TEEAttestationProof,
    config?: TEEAttestationConfig
  ): Promise<TEEAttestationSubmissionResult> {
    try {
      core.info('🔐 Submitting TEE attestation to smart contract for verification');

      // Validate inputs
      this.validateTEEAttestationInputs(siteRecordId, attestation, config);

      // Parse private key and get user address
      const keypair = this.parsePrivateKey(privateKey);
      const userAddress = keypair.getPublicKey().toSuiAddress();

      core.debug(`User address: ${userAddress}`);
      core.debug(`Site record ID: ${siteRecordId}`);
      core.debug(`Attestation domain: ${attestation.payload.domain}`);

      // Verify user owns the SiteRecord
      const siteRecord = await this.client.getObject({
        id: siteRecordId,
        options: { showOwner: true, showContent: true },
      });

      if (!siteRecord.data) {
        throw new SuiError(
          `SiteRecord ${siteRecordId} not found`,
          'SITE_RECORD_NOT_FOUND',
          { siteRecordId }
        );
      }

      // Check ownership
      const owner =
        (siteRecord.data.owner as any)?.AddressOwner ||
        (siteRecord.data.owner as any)?.ObjectOwner;
      if (owner !== userAddress) {
        throw new SuiError(
          `SiteRecord owned by ${owner}, signed by ${userAddress}`,
          'UNAUTHORIZED',
          { owner, signer: userAddress }
        );
      }

      // Check attestation age if configured
      if (config?.maxAttestationAge !== undefined) {
        const nowMs = Date.now();
        const ageMs = nowMs - attestation.payload.verification_timestamp;
        const maxAgeMs = config.maxAttestationAge * 1000;

        if (ageMs > maxAgeMs) {
          throw new SuiError(
            `Attestation is too old: ${Math.floor(ageMs / 1000)}s exceeds max ${config.maxAttestationAge}s`,
            'ATTESTATION_EXPIRED',
            { ageSeconds: Math.floor(ageMs / 1000), maxAgeSeconds: config.maxAttestationAge }
          );
        }
      }

      // Verify expected enclave measurement if configured
      if (config?.expectedEnclaveMeasurement) {
        const normalizedExpected = config.expectedEnclaveMeasurement.toLowerCase().replace('0x', '');
        const normalizedActual = attestation.enclave_measurement.toLowerCase().replace('0x', '');

        if (normalizedExpected !== normalizedActual) {
          throw new SuiError(
            'Enclave measurement does not match expected value',
            'MEASUREMENT_MISMATCH',
            {
              expected: config.expectedEnclaveMeasurement,
              actual: attestation.enclave_measurement,
            }
          );
        }
      }

      // Serialize attestation for smart contract
      core.debug('Serializing attestation proof for smart contract');
      const serialized: SerializedAttestationProof = serializeAttestationProof(attestation);

      core.debug(`Payload size: ${serialized.payload.length} bytes`);
      core.debug(`Signature size: ${serialized.signature.length} bytes`);
      core.debug(`Public key size: ${serialized.publicKey.length} bytes`);
      core.debug(`Measurement size: ${serialized.measurement.length} bytes`);

      // Get Trusted TEE Registry ID
      const trustedTeeRegistryId = this.getTrustedTEERegistryId(config);

      // Build transaction
      const tx = new Transaction();
      tx.setGasBudget(this.gasBudget);

      core.debug(`Building update_site_with_tee_attestation transaction`);
      core.debug(`Package ID: ${this.packageId}`);
      core.debug(`Trusted TEE Registry: ${trustedTeeRegistryId}`);

      // Call smart contract function
      // NOTE: Function name and argument order must match the contract implementation
      tx.moveCall({
        target: `${this.packageId}::site_registry::update_site_with_tee_attestation`,
        arguments: [
          tx.object(siteRecordId), // site_record: &mut SiteRecord
          tx.pure.vector('u8', Array.from(serialized.payload)), // attestation_payload: vector<u8>
          tx.pure.vector('u8', Array.from(serialized.signature)), // attestation_signature: vector<u8>
          tx.pure.vector('u8', Array.from(serialized.publicKey)), // tee_public_key: vector<u8>
          tx.pure.vector('u8', Array.from(serialized.measurement)), // enclave_measurement: vector<u8>
          tx.object(trustedTeeRegistryId), // trusted_tee_registry: &TrustedTEERegistry
          tx.object('0x6'), // clock: &Clock
        ],
      });

      // Sign and execute transaction
      core.debug('Signing and executing transaction');
      const result = await this.client.signAndExecuteTransaction({
        signer: keypair,
        transaction: tx,
        options: {
          showEffects: true,
          showEvents: true,
          showObjectChanges: true,
        },
      });

      core.debug(`Transaction submitted: ${result.digest}`);

      // Parse and return result
      const submissionResult = this.parseAttestationSubmissionResult(result);

      if (submissionResult.success) {
        core.info(`✅ TEE attestation verified on-chain`);
        core.info(`   Transaction: ${submissionResult.transactionDigest}`);
        core.info(`   New Version: ${submissionResult.newVersion}`);
        core.info(`   Gas Used: ${submissionResult.gasUsed} MIST`);
      } else {
        core.warning(`❌ TEE attestation verification failed: ${submissionResult.error}`);
      }

      return submissionResult;
    } catch (error) {
      // Re-throw SuiError as-is
      if (error instanceof SuiError) {
        throw error;
      }

      const errorMessage = error instanceof Error ? error.message : String(error);

      // Parse common error types
      if (errorMessage.includes('Insufficient gas')) {
        throw new SuiError(
          'Insufficient SUI tokens in wallet for gas fees',
          'INSUFFICIENT_GAS',
          { error: errorMessage }
        );
      } else if (
        errorMessage.includes('Version mismatch') ||
        errorMessage.includes('object version')
      ) {
        throw new SuiError(
          'Concurrent deployment detected - SiteRecord version mismatch',
          'VERSION_CONFLICT',
          { error: errorMessage }
        );
      } else if (errorMessage.includes('not found')) {
        throw new SuiError(
          'SiteRecord not found on blockchain',
          'SITE_RECORD_NOT_FOUND',
          { error: errorMessage }
        );
      } else if (
        errorMessage.includes('attestation') ||
        errorMessage.includes('signature') ||
        errorMessage.includes('verification')
      ) {
        throw new SuiError(
          `On-chain attestation verification failed: ${errorMessage}`,
          'ATTESTATION_VERIFICATION_FAILED',
          { error: errorMessage }
        );
      }

      throw new SuiError(
        `Failed to submit TEE attestation: ${errorMessage}`,
        'ATTESTATION_SUBMISSION_FAILED',
        { siteRecordId, error: errorMessage }
      );
    }
  }

  /**
   * Validate inputs for TEE attestation submission.
   * @private
   */
  private validateTEEAttestationInputs(
    siteRecordId: string,
    attestation: TEEAttestationProof,
    config?: TEEAttestationConfig
  ): void {
    // Validate site record ID
    if (!siteRecordId || typeof siteRecordId !== 'string') {
      throw new SuiError(
        'Site record ID is required',
        'INVALID_INPUT',
        { field: 'siteRecordId' }
      );
    }

    if (!siteRecordId.startsWith('0x')) {
      throw new SuiError(
        'Site record ID must be a valid Sui object ID (hex string with 0x prefix)',
        'INVALID_INPUT',
        { field: 'siteRecordId', value: siteRecordId }
      );
    }

    // Validate attestation
    if (!attestation || typeof attestation !== 'object') {
      throw new SuiError(
        'Attestation is required',
        'INVALID_INPUT',
        { field: 'attestation' }
      );
    }

    if (!attestation.payload) {
      throw new SuiError(
        'Attestation payload is required',
        'INVALID_INPUT',
        { field: 'attestation.payload' }
      );
    }

    if (!attestation.signature) {
      throw new SuiError(
        'Attestation signature is required',
        'INVALID_INPUT',
        { field: 'attestation.signature' }
      );
    }

    if (!attestation.public_key) {
      throw new SuiError(
        'Attestation public_key is required',
        'INVALID_INPUT',
        { field: 'attestation.public_key' }
      );
    }

    if (!attestation.enclave_measurement) {
      throw new SuiError(
        'Attestation enclave_measurement is required',
        'INVALID_INPUT',
        { field: 'attestation.enclave_measurement' }
      );
    }

    // Validate config if provided
    if (config?.trustedTeeRegistryId) {
      if (!config.trustedTeeRegistryId.startsWith('0x')) {
        throw new SuiError(
          'Trusted TEE Registry ID must be a valid Sui object ID',
          'INVALID_INPUT',
          { field: 'config.trustedTeeRegistryId', value: config.trustedTeeRegistryId }
        );
      }
    }

    if (config?.maxAttestationAge !== undefined && config.maxAttestationAge <= 0) {
      throw new SuiError(
        'maxAttestationAge must be a positive number',
        'INVALID_INPUT',
        { field: 'config.maxAttestationAge', value: config.maxAttestationAge }
      );
    }
  }

  /**
   * Get the Trusted TEE Registry object ID.
   * This registry contains approved TEE public keys and measurements.
   *
   * Precedence:
   * 1. config.trustedTeeRegistryId
   * 2. Environment variable TRUSTED_TEE_REGISTRY_ID
   * 3. Default for the current network (if available)
   *
   * @private
   * @param config - Optional configuration containing the registry ID
   * @returns Sui object ID of the Trusted TEE Registry
   * @throws SuiError if no registry ID is available
   */
  private getTrustedTEERegistryId(config?: TEEAttestationConfig): string {
    // Check config first
    if (config?.trustedTeeRegistryId) {
      return config.trustedTeeRegistryId;
    }

    // Check environment variable
    const envRegistryId = process.env.TRUSTED_TEE_REGISTRY_ID;
    if (envRegistryId) {
      return envRegistryId;
    }

    // Network-specific defaults (to be populated after contract deployment)
    const networkDefaults: Record<string, string | undefined> = {
      testnet: process.env.TRUSTED_TEE_REGISTRY_ID_TESTNET,
      mainnet: process.env.TRUSTED_TEE_REGISTRY_ID_MAINNET,
      localnet: process.env.TRUSTED_TEE_REGISTRY_ID_LOCALNET,
    };

    const networkDefault = networkDefaults[this.network];
    if (networkDefault) {
      return networkDefault;
    }

    throw new SuiError(
      'Trusted TEE Registry ID not configured. Set TRUSTED_TEE_REGISTRY_ID environment variable or provide trustedTeeRegistryId in config.',
      'REGISTRY_NOT_CONFIGURED',
      { network: this.network }
    );
  }

  /**
   * Parse transaction result for attestation submission.
   * Extracts verification details from transaction events and effects.
   *
   * @private
   * @param result - Raw transaction result from Sui RPC
   * @returns Parsed submission result with verification details
   */
  private parseAttestationSubmissionResult(
    result: SuiTransactionBlockResponse
  ): TEEAttestationSubmissionResult {
    const effects = result.effects;

    // Check if transaction failed
    if (effects?.status?.status !== 'success') {
      const errorMsg = effects?.status?.error || 'Transaction failed';

      // Parse error to determine verification failure type
      const onChainVerification = this.parseVerificationError(errorMsg);

      return {
        success: false,
        transactionDigest: result.digest,
        newVersion: 0,
        gasUsed: this.calculateGasUsed(effects),
        onChainVerification,
        error: errorMsg,
      };
    }

    // Transaction succeeded - all on-chain verifications passed
    // Extract new version from events
    let newVersion = 0;
    if (result.events) {
      const updateEvent = result.events.find(
        (e) =>
          e.type.includes('SiteUpdated') ||
          e.type.includes('SiteDataUpdated') ||
          e.type.includes('TEEAttestationVerified')
      );

      if (updateEvent?.parsedJson) {
        const parsedJson = updateEvent.parsedJson as Record<string, any>;
        newVersion = Number(
          parsedJson.version || parsedJson.new_version || parsedJson.newVersion || 0
        );
      }
    }

    return {
      success: true,
      transactionDigest: result.digest,
      newVersion,
      gasUsed: this.calculateGasUsed(effects),
      onChainVerification: {
        signatureValid: true,
        measurementValid: true,
        payloadValid: true,
        notExpired: true,
      },
    };
  }

  /**
   * Parse verification error message to determine which check failed.
   * @private
   */
  private parseVerificationError(error: string): TEEAttestationSubmissionResult['onChainVerification'] {
    const lowerError = error.toLowerCase();

    return {
      signatureValid: !lowerError.includes('signature'),
      measurementValid: !lowerError.includes('measurement'),
      payloadValid: !lowerError.includes('payload') && !lowerError.includes('deserialize'),
      notExpired: !lowerError.includes('expired') && !lowerError.includes('expiry'),
    };
  }

  /**
   * Calculate total gas used from transaction effects.
   * @private
   */
  private calculateGasUsed(
    effects: SuiTransactionBlockResponse['effects']
  ): number {
    if (!effects?.gasUsed) {
      return 0;
    }

    return (
      Number(effects.gasUsed.computationCost || 0) +
      Number(effects.gasUsed.storageCost || 0) -
      Number(effects.gasUsed.storageRebate || 0)
    );
  }

  // ============================================================================
  // Trustless Direct Update Methods
  // ============================================================================

  /**
   * Direct site update without server attestation.
   * The user signs and submits the transaction directly using their own private key.
   *
   * This is the trustless flow where:
   * 1. Pre-verification is done by the server (read-only check)
   * 2. User uploads to Walrus with their own credentials
   * 3. User signs and submits blockchain transaction directly
   *
   * No server involvement in blockchain writes - fully trustless!
   *
   * @param privateKey - Owner's private key for transaction signing
   * @param siteRecordId - Sui object ID of the site record
   * @param deploymentData - Deployment data including quilt IDs and metadata
   * @returns Transaction result
   */
  async updateSiteDirect(
    privateKey: string,
    siteRecordId: string,
    deploymentData: {
      content_quilt_id: string;
      metadata_quilt_id: string;
      provenance_blob_id: string;
      files_manifest_hash: string;
      total_files: number;
      total_size_bytes: number;
      github_repo: string;
      github_commit_sha: string;
      github_workflow_ref: string;
      github_run_id: number;
    }
  ): Promise<TransactionResult> {
    try {
      core.info('🔐 Submitting direct site update (trustless - user signed)');

      // Parse private key and get user address
      const keypair = this.parsePrivateKey(privateKey);
      const userAddress = keypair.getPublicKey().toSuiAddress();

      core.debug(`User address: ${userAddress}`);
      core.debug(`Site record ID: ${siteRecordId}`);

      // Verify user owns the SiteRecord
      const siteRecord = await this.client.getObject({
        id: siteRecordId,
        options: { showOwner: true, showContent: true },
      });

      if (!siteRecord.data) {
        throw new SuiError(
          `SiteRecord ${siteRecordId} not found`,
          'SITE_RECORD_NOT_FOUND',
          { siteRecordId }
        );
      }

      // Check ownership
      const owner =
        (siteRecord.data.owner as any)?.AddressOwner ||
        (siteRecord.data.owner as any)?.ObjectOwner;
      if (owner !== userAddress) {
        throw new SuiError(
          `SiteRecord owned by ${owner}, signed by ${userAddress}`,
          'UNAUTHORIZED',
          { owner, signer: userAddress }
        );
      }

      // Build transaction
      const tx = new Transaction();
      tx.setGasBudget(this.gasBudget);

      core.debug(`Building update_site_data_with_quilt transaction`);
      core.debug(`Package ID: ${this.packageId}`);

      // Get current version from site record for expected_version check
      const siteContent = siteRecord.data.content as any;
      const currentVersion = siteContent?.fields?.current_version || '0';
      core.debug(`Current version: ${currentVersion}`);

      // Call smart contract function for site update
      // Uses the existing update_site_data_with_quilt function from domain_registry
      // The contract verifies caller ownership and expected version
      tx.moveCall({
        target: `${this.packageId}::domain_registry::update_site_data_with_quilt`,
        arguments: [
          tx.object(this.registryId), // registry: &mut Registry
          tx.object(siteRecordId), // site_record: &mut SiteRecord
          tx.pure.string(deploymentData.metadata_quilt_id), // quilt_blob_id (contains manifest + attestation)
          tx.pure.string(deploymentData.github_commit_sha), // github_commit_sha
          tx.pure.string('SLSA_LEVEL_3'), // slsa_level
          tx.pure.u64(BigInt(currentVersion)), // expected_version
          tx.object('0x6'), // clock: &Clock
        ],
      });

      // Sign and execute transaction
      core.debug('Signing and executing transaction');
      const result = await this.client.signAndExecuteTransaction({
        signer: keypair,
        transaction: tx,
        options: {
          showEffects: true,
          showEvents: true,
          showObjectChanges: true,
        },
      });

      core.debug(`Transaction submitted: ${result.digest}`);

      // Check transaction status
      if (result.effects?.status?.status !== 'success') {
        const error = result.effects?.status?.error || 'Unknown error';
        throw new SuiError(
          `Transaction failed: ${error}`,
          'TRANSACTION_FAILED',
          { digest: result.digest, error }
        );
      }

      // Extract new version from events
      let newVersion = '0';
      if (result.events) {
        const updateEvent = result.events.find((e: any) =>
          e.type.includes('SiteUpdated') ||
          e.type.includes('SiteDataUpdated') ||
          e.type.includes('::domain_registry::')
        );
        if (updateEvent && updateEvent.parsedJson) {
          const parsedJson = updateEvent.parsedJson as Record<string, any>;
          newVersion = String(parsedJson.version || parsedJson.new_version || parsedJson.newVersion || '0');
        }
      }

      // Calculate gas used
      const gasUsed = this.calculateGasUsed(result.effects);

      core.info(`✅ Direct site update successful`);
      core.info(`   Transaction: ${result.digest}`);
      core.info(`   New Version: ${newVersion}`);
      core.info(`   Gas Used: ${gasUsed} MIST`);

      return {
        digest: result.digest,
        status: 'success',
        newVersion,
        gasUsed,
      };

    } catch (error) {
      if (error instanceof SuiError) {
        throw error;
      }

      const errorMessage = error instanceof Error ? error.message : String(error);

      // Parse common error types
      if (errorMessage.includes('Insufficient gas')) {
        throw new SuiError(
          'Insufficient SUI tokens in wallet for gas fees',
          'INSUFFICIENT_GAS',
          { error: errorMessage }
        );
      } else if (
        errorMessage.includes('Version mismatch') ||
        errorMessage.includes('object version')
      ) {
        throw new SuiError(
          'Concurrent deployment detected - SiteRecord version mismatch',
          'VERSION_CONFLICT',
          { error: errorMessage }
        );
      } else if (errorMessage.includes('not found')) {
        throw new SuiError(
          'SiteRecord not found on blockchain',
          'SITE_RECORD_NOT_FOUND',
          { error: errorMessage }
        );
      }

      throw new SuiError(
        `Direct site update failed: ${errorMessage}`,
        'UPDATE_FAILED',
        { siteRecordId, error: errorMessage }
      );
    }
  }
}
