import * as core from '@actions/core';

/**
 * Configuration for Walrus client
 */
export interface WalrusClientConfig {
  publisherUrl: string;
  aggregatorUrl?: string;
  timeout?: number;
  maxRetries?: number;
}

/**
 * Result of a Walrus blob upload
 */
export interface WalrusBlobInfo {
  blobId: string;
  size: number;
  uploadDuration: number;
}

/**
 * Error thrown by Walrus operations
 */
export class WalrusError extends Error {
  constructor(
    message: string,
    public code: string,
    public details?: any
  ) {
    super(message);
    this.name = 'WalrusError';
  }
}

/**
 * Quilt structure for organizing related blobs
 */
export interface QuiltManifest {
  version: string;
  files: Array<{
    path: string;
    blobId: string;
    size: number;
    contentType: string;
  }>;
  metadata?: Record<string, any>;
}

/**
 * Two-quilt deployment structure
 */
export interface TwoQuiltDeployment {
  contentQuilt: {
    blobId: string;
    manifest: QuiltManifest;
    totalSize: number;
  };
  metadataQuilt: {
    blobId: string;
    manifest: QuiltManifest;
    totalSize: number;
  };
}

/**
 * Client for interacting with Walrus decentralized storage
 * Handles file uploads and blob verification with quilt support
 */
export class WalrusClient {
  private readonly publisherUrl: string;
  private readonly aggregatorUrl: string;
  private readonly timeout: number;
  private readonly maxRetries: number;

  constructor(config: WalrusClientConfig) {
    this.publisherUrl = config.publisherUrl;
    this.aggregatorUrl = config.aggregatorUrl || config.publisherUrl.replace('publisher', 'aggregator');
    this.timeout = config.timeout || 30000; // 30 seconds default
    this.maxRetries = config.maxRetries || 3;
  }

  /**
   * Upload a file to Walrus storage
   * @param fileContent - File content as Buffer or string
   * @param fileName - Optional file name for logging
   * @returns Blob information including blob ID
   */
  async uploadBlob(fileContent: Buffer | string, fileName?: string): Promise<WalrusBlobInfo> {
    const startTime = Date.now();
    const content = Buffer.isBuffer(fileContent) ? fileContent : Buffer.from(fileContent, 'utf-8');

    core.debug(`Uploading blob${fileName ? ` (${fileName})` : ''} to Walrus (${content.length} bytes)`);

    let lastError: Error | undefined;

    for (let attempt = 1; attempt <= this.maxRetries; attempt++) {
      try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), this.timeout);

        const response = await (globalThis.fetch || fetch)(`${this.publisherUrl}/v1/blobs`, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/octet-stream',
          },
          body: content as BodyInit,
          signal: controller.signal as AbortSignal,
        });

        clearTimeout(timeoutId);

        if (!response.ok) {
          const errorText = await response.text();
          throw new WalrusError(
            `Walrus upload failed: ${response.status} ${response.statusText}`,
            'UPLOAD_FAILED',
            { status: response.status, body: errorText }
          );
        }

        const result = await response.json() as any;

        // Walrus returns different response formats depending on whether blob is new or already exists
        let blobId: string;

        if (result.newlyCreated) {
          // New blob was created
          blobId = result.newlyCreated.blobObject?.blobId || result.newlyCreated.blobId;
        } else if (result.alreadyCertified) {
          // Blob already exists and is certified
          blobId = result.alreadyCertified.blobId || result.alreadyCertified.blobObject?.blobId;
        } else {
          throw new WalrusError(
            'Unexpected Walrus response format',
            'INVALID_RESPONSE',
            { response: result }
          );
        }

        if (!blobId) {
          throw new WalrusError(
            'Blob ID not found in Walrus response',
            'MISSING_BLOB_ID',
            { response: result }
          );
        }

        const uploadDuration = Date.now() - startTime;

        core.debug(`✅ Blob uploaded successfully: ${blobId} (${uploadDuration}ms)`);

        return {
          blobId,
          size: content.length,
          uploadDuration,
        };

      } catch (error) {
        lastError = error instanceof Error ? error : new Error(String(error));

        if (error instanceof WalrusError) {
          // Don't retry on certain error codes
          if (error.code === 'INVALID_RESPONSE' || error.code === 'MISSING_BLOB_ID') {
            throw error;
          }
        }

        if (attempt < this.maxRetries) {
          const delay = Math.min(1000 * Math.pow(2, attempt - 1), 5000); // Exponential backoff, max 5s
          core.warning(`Walrus upload attempt ${attempt} failed, retrying in ${delay}ms: ${lastError.message}`);
          await this.sleep(delay);
        }
      }
    }

    throw new WalrusError(
      `Failed to upload blob after ${this.maxRetries} attempts: ${lastError?.message}`,
      'MAX_RETRIES_EXCEEDED',
      { lastError: lastError?.message }
    );
  }

  /**
   * Upload multiple blobs in parallel
   * @param files - Map of file path to file content
   * @param concurrency - Max number of parallel uploads
   * @returns Map of file path to blob ID
   */
  async uploadBlobs(
    files: Record<string, Buffer | string>,
    concurrency: number = 5
  ): Promise<Record<string, string>> {
    const entries = Object.entries(files);
    const results: Record<string, string> = {};

    core.debug(`Uploading ${entries.length} files (concurrency: ${concurrency})`);

    // Process in batches
    for (let i = 0; i < entries.length; i += concurrency) {
      const batch = entries.slice(i, i + concurrency);

      const batchResults = await Promise.all(
        batch.map(async ([path, content]) => {
          const blobInfo = await this.uploadBlob(content, path);
          core.debug(`Uploaded ${path} → ${blobInfo.blobId}`);
          return { path, blobId: blobInfo.blobId };
        })
      );

      for (const { path, blobId } of batchResults) {
        results[path] = blobId;
      }
    }

    return results;
  }

  /**
   * Verify that a blob exists in Walrus
   * @param blobId - Blob ID to verify
   * @returns True if blob exists and is accessible
   */
  async verifyBlob(blobId: string): Promise<boolean> {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), this.timeout);

      const response = await (globalThis.fetch || fetch)(`${this.aggregatorUrl}/v1/${blobId}`, {
        method: 'HEAD',
        signal: controller.signal as AbortSignal,
      });

      clearTimeout(timeoutId);

      return response.ok;
    } catch (error) {
      core.warning(`Failed to verify blob ${blobId}: ${error instanceof Error ? error.message : String(error)}`);
      return false;
    }
  }

  /**
   * Upload files using two-quilt structure (content + metadata)
   * This matches the structure used by the verification server
   *
   * @param files - Map of file path to file content
   * @param provenance - Provenance data
   * @param manifest - CryptoGuard manifest data (framework routing info)
   * @param metadata - Additional metadata
   * @returns Two-quilt deployment structure
   */
  async uploadTwoQuiltStructure(
    files: Record<string, Buffer>,
    provenance: any,
    manifest: any,
    metadata?: Record<string, any>
  ): Promise<TwoQuiltDeployment> {
    // Upload individual file blobs
    const fileBlobInfos: Array<{ path: string; blobId: string; size: number; contentType: string }> = [];

    for (const [filePath, fileContent] of Object.entries(files)) {
      const blobInfo = await this.uploadBlob(fileContent, filePath);
      const contentType = this.getContentType(filePath);

      fileBlobInfos.push({
        path: filePath,
        blobId: blobInfo.blobId,
        size: blobInfo.size,
        contentType,
      });

      core.debug(`Uploaded ${filePath} → ${blobInfo.blobId}`);
    }

    // Create and upload content quilt manifest
    const contentQuiltManifest: QuiltManifest = {
      version: '1.0',
      files: fileBlobInfos,
      metadata: {
        created_at: new Date().toISOString(),
        total_files: fileBlobInfos.length,
        total_size: fileBlobInfos.reduce((sum, f) => sum + f.size, 0),
      },
    };

    const contentQuiltBlob = await this.uploadBlob(
      JSON.stringify(contentQuiltManifest, null, 2),
      'content-quilt-manifest.json'
    );

    core.debug(`Content quilt created: ${contentQuiltBlob.blobId}`);

    // Create metadata quilt with ONLY 2 files: provenance.json + manifest.json
    // (provenance and manifest are embedded directly, NOT uploaded as separate blobs)
    const metadataQuiltManifest: QuiltManifest = {
      version: '1.0',
      files: [
        {
          path: 'provenance.json',
          blobId: '', // Embedded in quilt, not separate blob
          size: JSON.stringify(provenance).length,
          contentType: 'application/json',
        },
        {
          path: 'manifest.json',
          blobId: '', // Embedded in quilt, not separate blob
          size: JSON.stringify(manifest).length,
          contentType: 'application/json',
        },
      ],
      metadata: {
        ...metadata,
        created_at: new Date().toISOString(),
        content_quilt_id: contentQuiltBlob.blobId,
        framework: manifest.framework,
        framework_version: manifest.frameworkVersion,
        deployment_type: 'two-quilt-structure',
        // Embed the actual content
        provenance,
        manifest,
      },
    };

    const metadataQuiltBlob = await this.uploadBlob(
      JSON.stringify(metadataQuiltManifest, null, 2),
      'metadata-quilt-manifest.json'
    );

    core.debug(`Metadata quilt created: ${metadataQuiltBlob.blobId} (contains provenance + manifest)`);

    return {
      contentQuilt: {
        blobId: contentQuiltBlob.blobId,
        manifest: contentQuiltManifest,
        totalSize: contentQuiltBlob.size,
      },
      metadataQuilt: {
        blobId: metadataQuiltBlob.blobId,
        manifest: metadataQuiltManifest,
        totalSize: metadataQuiltBlob.size,
      },
    };
  }

  /**
   * Get content type from file extension
   */
  private getContentType(filePath: string): string {
    const ext = filePath.split('.').pop()?.toLowerCase();
    const contentTypes: Record<string, string> = {
      html: 'text/html',
      css: 'text/css',
      js: 'application/javascript',
      json: 'application/json',
      png: 'image/png',
      jpg: 'image/jpeg',
      jpeg: 'image/jpeg',
      gif: 'image/gif',
      svg: 'image/svg+xml',
      woff: 'font/woff',
      woff2: 'font/woff2',
      ttf: 'font/ttf',
      ico: 'image/x-icon',
    };
    return contentTypes[ext || ''] || 'application/octet-stream';
  }

  /**
   * Sleep for specified milliseconds
   */
  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}
